      "claim": "Sertindole has an oral bioavailability of 75% in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C63"],
      "claim": "Abemaciclib has an absolute oral bioavailability of about 46% in healthy subjects, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Tepotinib has an absolute oral bioavailability of 72% in healthy volunteers, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
