      "claim": "Aprepitant has an absolute oral bioavailability of 59% for the 125-mg capsule formulation, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Paliperidone extended-release has an absolute oral bioavailability of 28%, still above the 20% threshold and representing the lower end of the analogue range.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer analogues have measured absolute oral bioavailability values above 20%, ranging from 28% to 87%, with most in the 45–75% range. The query shares relevant piperazine, heteroaryl, amide, and fluorophenyl features with these analogues, supporting a high oral bioavailability prediction.",
